API Gateway.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the API Gateway container

Container_Boundary(api_gateway, "API Gateway") {
    Component(Ingress_Router, "Ingress Router", "Traefik/NGINX", "Handles high-performance ingress routing, SSL termination, and active-active hybrid deployment.")
    Component(Authentication_Manager, "Authentication Manager", "OAuth2/OIDC with MFA", "Secures external access and validates tokens for incoming client requests.")
}

Rel(Ingress_Router, Authentication_Manager, "Validates incoming user credentials and tokens", "HTTPS/REST")

@enduml

HashiCorp Vault.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(vault, "HashiCorp Vault") {
    Component(Secrets Engine, "Secrets Engine", "HashiCorp Vault KV/Database Secrets Engines", "Manages and provides dynamic credentials and data encryption.")
    Component(Auth Methods, "Auth Methods", "HashiCorp Vault AppRole, Kubernetes Auth", "Handles client authentication and mTLS token acquisition.")
    Component(Audit Log, "Audit Log", "HashiCorp Vault Audit Component", "Tracks and exports system audit logs for SIEM ingestion.")
    Component(Storage Backend Integration, "Storage Backend Integration", "HashiCorp Vault Raft storage, AWS KMS/HSM auto-unseal", "Manages persistent encrypted storage and disaster recovery snapshots.")
}

Rel(Auth Methods, Secrets Engine, "Grants access after authentication")
Rel(Audit Log, Storage Backend Integration, "Persists audit data")
@enduml

OpenTelemetry Collector.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(OpenTelemetry_Collector, "OpenTelemetry Collector") {
    Component(OpenTelemetry_Receiver, "OpenTelemetry Receiver", "OpenTelemetry Protocol (OTLP)", "Receives metrics, traces, and logs from backend services via OTLP/gRPC with mTLS.")
    Component(PII_PHI_Redaction_Processor, "PII/PHI Redaction Processor", "Custom Filtering Processor", "Redacts personally identifiable information (PII) and protected health information (PHI) to ensure HIPAA/GDPR compliance.")
    Component(Telemetry_Exporter, "Telemetry Exporter", "OpenTelemetry Exporter", "Transmits unified metrics, traces, and logs to observability backends.")
}

Rel(OpenTelemetry_Receiver, PII_PHI_Redaction_Processor, "Passes raw telemetry data for redaction")
Rel(PII_PHI_Redaction_Processor, Telemetry_Exporter, "Sends sanitized telemetry data for export")
@enduml
